//! Port of `client/js/gui/vanilla-layout.js`: `VANILLA_UI` constants.
//!
//! Generated by `tools/extract-gui.mjs` from the pinned client jar.
//! Contains vanilla UI layout constants: video options, control options,
//! key binding categories, chat options, and button text colors.

/// Vanilla UI layout constants (port of `VANILLA_UI`).
#[derive(Debug, Clone)]
pub struct VanillaUI {
    /// Version string.
    pub version: &'static str,
    /// Client JAR SHA-1.
    pub client_jar_sha1: &'static str,
    /// Pack format version.
    pub pack_format: i32,
    /// Video settings options (keys in `options.*` namespace).
    pub video_options: &'static [&'static str],
    /// Control settings options.
    pub control_options: &'static [&'static str],
    /// Category order (empty in 1.8.9).
    pub category_order: &'static [&'static str],
    /// Key binding categories (key -> category mapping).
    pub binding_categories: &'static [(&'static str, &'static str)],
    /// Chat settings options.
    pub chat_options: &'static [&'static str],
    /// Button text colors.
    pub button_text: ButtonTextColors,
}

/// Button text colors (ARGB format).
#[derive(Debug, Clone, Copy)]
pub struct ButtonTextColors {
    /// Normal button text color.
    pub normal: u32,
    /// Hover button text color.
    pub hover: u32,
}

