#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn vanilla_ui_version() {
        assert_eq!(VANILLA_UI.version, "1.8.9");
    }

    #[test]
    fn vanilla_ui_video_options_count() {
        assert_eq!(VANILLA_UI.video_options.len(), 16);
    }

    #[test]
    fn vanilla_ui_control_options_count() {
        assert_eq!(VANILLA_UI.control_options.len(), 3);
    }

    #[test]
    fn vanilla_ui_binding_categories_count() {
        assert_eq!(VANILLA_UI.binding_categories.len(), 31);
    }

    #[test]
    fn vanilla_ui_chat_options_count() {
        assert_eq!(VANILLA_UI.chat_options.len(), 10);
    }

    #[test]
    fn vanilla_ui_button_text_colors() {
        assert_eq!(VANILLA_UI.button_text.normal, 14737632);
        assert_eq!(VANILLA_UI.button_text.hover, 16777120);
    }

    #[test]
    fn vanilla_ui_pack_format() {
        assert_eq!(VANILLA_UI.pack_format, 1);
    }
}